//! 🗑️ Deleted rows retain genuine original-field preparation and inverse command custody.
use crate::LayoutMutation;
use super::super::simple::SimpleKind;
use semio_s_artifact_layout_layout_model::{snapshot::LayoutSnapshot,ImageLink,TextStory,ParagraphStyle,CharacterStyle,Spread,ParentPage};
use semio_framework_os_kernel::{RetainedFieldPreparation,RetainedMutationCloseContext};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use semio_framework_value_factory::vector::FactoryVectorRetirement;
use std::mem::{size_of,ManuallyDrop};
fn fault()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"deleted Layout row inverse custody is invalid")}
fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<LayoutMutation>()*4+512,depth:1,..Default::default()}}
fn nested(mut d:RetirementDemand)->RetirementDemand{d.copy_bytes+=256;d.depth+=1;d}
fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-256,maximum_depth:g.maximum_depth-1,..g}}
fn receipt(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_bytes+=256;p.copied_items=p.copied_items.max(1);p}
fn refused(e:ValueError)->ValueError{let p=receipt(e.retained_progress());e.with_retained_progress(p)}
fn source_link<'a>(b:RetainedCloneRef<'a,LayoutSnapshot>,at:usize)->RetainedCloneRef<'a,ImageLink>{b.project(6,|b|&b.links).project(at,move|rows|&rows[at])}
fn source_story<'a>(b:RetainedCloneRef<'a,LayoutSnapshot>,at:usize)->RetainedCloneRef<'a,TextStory>{b.project(5,|b|&b.stories).project(at,move|rows|&rows[at])}
fn source_paragraph<'a>(b:RetainedCloneRef<'a,LayoutSnapshot>,at:usize)->RetainedCloneRef<'a,ParagraphStyle>{b.project(3,|b|&b.paragraph_styles).project(at,move|rows|&rows[at])}
fn source_character<'a>(b:RetainedCloneRef<'a,LayoutSnapshot>,at:usize)->RetainedCloneRef<'a,CharacterStyle>{b.project(4,|b|&b.character_styles).project(at,move|rows|&rows[at])}
fn source_spread<'a>(b:RetainedCloneRef<'a,LayoutSnapshot>,at:usize)->RetainedCloneRef<'a,Spread>{b.project(8,|b|&b.spreads).project(at,move|rows|&rows[at])}
fn source_parent<'a>(b:RetainedCloneRef<'a,LayoutSnapshot>,at:usize)->RetainedCloneRef<'a,ParentPage>{b.project(7,|b|&b.parent_pages).project(at,move|rows|&rows[at])}
/// 🧳 Only the deleted row and a required duplicate identifier become new owned inverse sources.
pub struct DeletionInverse{parent:RetainedFieldPreparation<ParentPage>,link:RetainedFieldPreparation<ImageLink>,story:RetainedFieldPreparation<TextStory>,paragraph:RetainedFieldPreparation<ParagraphStyle>,character:RetainedFieldPreparation<CharacterStyle>,spread:RetainedFieldPreparation<Spread>,id:RetainedFieldPreparation<String>,rows:ManuallyDrop<Option<Vec<LayoutMutation>>>,retirement:Option<FactoryVectorRetirement<LayoutMutation>>,phase:u8,closing:bool}
impl Default for DeletionInverse{fn default()->Self{Self{parent:Default::default(),link:Default::default(),story:Default::default(),paragraph:Default::default(),character:Default::default(),spread:Default::default(),id:Default::default(),rows:ManuallyDrop::new(None),retirement:None,phase:0,closing:false}}}
impl DeletionInverse{
 pub fn ready(&self)->bool{self.phase==5}
 pub fn demand(&self,kind:SimpleKind,at:[usize;2],b:RetainedCloneRef<'_,LayoutSnapshot>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||!kind.delete(){return Err(fault())}Ok(match self.phase{0=>RetirementDemand{capacity_bytes:size_of::<LayoutMutation>()*if kind==SimpleKind::DeleteCharacterStyle{2}else{1},..fixed()},1=>match kind{SimpleKind::DeleteParentPage=>if self.parent.value().is_some(){fixed()}else{nested(self.parent.demand(source_parent(b,at[0]),body.saturating_sub(256))?)},SimpleKind::DeleteLink=>if self.link.value().is_some(){fixed()}else{nested(self.link.demand(source_link(b,at[0]),body.saturating_sub(256))?)},SimpleKind::DeleteStory=>if self.story.value().is_some(){fixed()}else{nested(self.story.demand(source_story(b,at[0]),body.saturating_sub(256))?)},SimpleKind::DeleteParagraphStyle=>if self.paragraph.value().is_some(){fixed()}else{nested(self.paragraph.demand(source_paragraph(b,at[0]),body.saturating_sub(256))?)},SimpleKind::DeleteCharacterStyle=>if self.character.value().is_some(){fixed()}else{nested(self.character.demand(source_character(b,at[0]),body.saturating_sub(256))?)},SimpleKind::DeleteSpread=>if self.spread.value().is_some(){fixed()}else{nested(self.spread.demand(source_spread(b,at[0]),body.saturating_sub(256))?)},_=>return Err(fault())},2=>if kind==SimpleKind::DeleteCharacterStyle&&self.id.value().is_none(){nested(self.id.demand(source_character(b,at[0]).project(0,|row|&row.id),body.saturating_sub(256))?)}else{fixed()},3=>{let mut d=nested(match kind{SimpleKind::DeleteParentPage=>self.parent.exchange_demand()?,SimpleKind::DeleteLink=>self.link.exchange_demand()?,SimpleKind::DeleteStory=>self.story.exchange_demand()?,SimpleKind::DeleteParagraphStyle=>self.paragraph.exchange_demand()?,SimpleKind::DeleteCharacterStyle=>self.id.exchange_demand()?,SimpleKind::DeleteSpread=>self.spread.exchange_demand()?,_=>return Err(fault())});d.copy_bytes+=size_of::<LayoutMutation>()*2;d},4=>{let mut d=nested(self.character.exchange_demand()?);d.copy_bytes+=size_of::<LayoutMutation>()*2;d},5|7=>fixed(),_=>return Err(fault())})}
 pub fn advance(&mut self,kind:SimpleKind,at:[usize;2],b:RetainedCloneRef<'_,LayoutSnapshot>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(kind,at,b,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};match self.phase{0=>{self.phase=254;*self.rows=Some(Vec::new());let rows=self.rows.as_mut().unwrap();let n=if kind==SimpleKind::DeleteCharacterStyle{2}else{1};let reserved=rows.try_reserve_exact(n);p.retained_capacity_bytes=rows.capacity()*size_of::<LayoutMutation>();if reserved.is_err()||p.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(p))}self.phase=1},1=>match kind{SimpleKind::DeleteParentPage=>if self.parent.value().is_some(){self.phase=2}else{p=receipt(self.parent.advance(source_parent(b,at[0]),body.saturating_sub(256),child(g)).map_err(refused)?.progress())},SimpleKind::DeleteLink=>if self.link.value().is_some(){self.phase=2}else{p=receipt(self.link.advance(source_link(b,at[0]),body.saturating_sub(256),child(g)).map_err(refused)?.progress())},SimpleKind::DeleteStory=>if self.story.value().is_some(){self.phase=2}else{p=receipt(self.story.advance(source_story(b,at[0]),body.saturating_sub(256),child(g)).map_err(refused)?.progress())},SimpleKind::DeleteParagraphStyle=>if self.paragraph.value().is_some(){self.phase=2}else{p=receipt(self.paragraph.advance(source_paragraph(b,at[0]),body.saturating_sub(256),child(g)).map_err(refused)?.progress())},SimpleKind::DeleteCharacterStyle=>if self.character.value().is_some(){self.phase=2}else{p=receipt(self.character.advance(source_character(b,at[0]),body.saturating_sub(256),child(g)).map_err(refused)?.progress())},SimpleKind::DeleteSpread=>if self.spread.value().is_some(){self.phase=2}else{p=receipt(self.spread.advance(source_spread(b,at[0]),body.saturating_sub(256),child(g)).map_err(refused)?.progress())},_=>return Err(fault())},2=>if kind==SimpleKind::DeleteCharacterStyle{if self.id.value().is_some(){self.phase=3}else{p=receipt(self.id.advance(source_character(b,at[0]).project(0,|row|&row.id),body.saturating_sub(256),child(g)).map_err(refused)?.progress())}}else{self.phase=3},3=>{let inner=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-256-size_of::<LayoutMutation>()*2,maximum_depth:g.maximum_depth-1,..g};match kind{SimpleKind::DeleteParentPage=>{let(value,paid)=self.parent.take(inner).map_err(refused)?;p=receipt(paid);self.rows.as_mut().unwrap().push(LayoutMutation::CreateParentPage(crate::create_parent_page::CreateParentPage{page:value.expect("original deleted parent row"),index:Some(at[0])}));self.phase=5},SimpleKind::DeleteLink=>{let(value,paid)=self.link.take(inner).map_err(refused)?;p=receipt(paid);self.rows.as_mut().unwrap().push(LayoutMutation::CreateLink(crate::create_link::CreateLink{link:value.expect("original deleted link row"),index:Some(at[0])}));self.phase=5},SimpleKind::DeleteStory=>{let(value,paid)=self.story.take(inner).map_err(refused)?;p=receipt(paid);self.rows.as_mut().unwrap().push(LayoutMutation::CreateStory(crate::create_story::CreateStory{story:value.expect("original deleted story row"),index:Some(at[0])}));self.phase=5},SimpleKind::DeleteParagraphStyle=>{let(value,paid)=self.paragraph.take(inner).map_err(refused)?;p=receipt(paid);self.rows.as_mut().unwrap().push(LayoutMutation::CreateParagraphStyle(crate::create_paragraph_style::CreateParagraphStyle{style:value.expect("original deleted paragraph row"),index:Some(at[0])}));self.phase=5},SimpleKind::DeleteSpread=>{let(value,paid)=self.spread.take(inner).map_err(refused)?;p=receipt(paid);self.rows.as_mut().unwrap().push(LayoutMutation::CreateSpread(crate::create_spread::CreateSpread{spread:value.expect("original deleted spread row"),index:Some(at[0])}));self.phase=5},SimpleKind::DeleteCharacterStyle=>{let(id,paid)=self.id.take(inner).map_err(refused)?;p=receipt(paid);self.rows.as_mut().unwrap().push(LayoutMutation::CreateCharacterStyle(crate::create_character_style::CreateCharacterStyle{id:id.expect("original second character identifier"),name:None,index:Some(at[0])}));self.phase=4},_=>return Err(fault())}p.copied_bytes+=size_of::<LayoutMutation>()*2},4=>{let(value,paid)=self.character.take(RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-256-size_of::<LayoutMutation>()*2,maximum_depth:g.maximum_depth-1,..g}).map_err(refused)?;p=receipt(paid);p.copied_bytes+=size_of::<LayoutMutation>()*2;let row=value.expect("original deleted character style");self.rows.as_mut().unwrap().push(LayoutMutation::UpdateCharacterStyle(crate::update_character_style::UpdateCharacterStyle{id:row.id,name:row.name,font_family:row.font_family,font_size:row.font_size,font_weight:row.font_weight,italic:row.italic,color:row.color,tracking:row.tracking}));self.phase=7},7=>{self.rows.as_mut().unwrap().swap(0,1);self.phase=5},5=>return Ok(RetainedCloneStep::Complete(p)),_=>return Err(fault())}if self.phase==5{Ok(RetainedCloneStep::Complete(p))}else{Ok(RetainedCloneStep::Progress(p))}}
 pub fn take_demand(&self)->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<Vec<LayoutMutation>>>()*2,depth:1,..Default::default()}}
 pub fn take(&mut self,g:RetainedCloneGrant)->Result<(Option<Vec<LayoutMutation>>,RetainedCloneProgress),ValueError>{if !self.ready()||self.closing{return Err(fault())}let d=self.take_demand();if !retained_clone_grant_admits(g,d){return Ok((None,Default::default()))}self.phase=6;Ok((self.rows.take(),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 pub fn begin_close(&mut self){self.closing=true;self.parent.begin_close();self.link.begin_close();self.story.begin_close();self.paragraph.begin_close();self.character.begin_close();self.spread.begin_close();self.id.begin_close()}
 pub fn close_demand(&self,c:RetainedMutationCloseContext<'_,LayoutMutation>,body:usize)->Result<RetirementDemand,ValueError>{if !self.parent.terminal_is_empty(){return self.parent.close_demand(body)}if !self.link.terminal_is_empty(){return self.link.close_demand(body)}if !self.story.terminal_is_empty(){return self.story.close_demand(body)}if !self.paragraph.terminal_is_empty(){return self.paragraph.close_demand(body)}if !self.character.terminal_is_empty(){return self.character.close_demand(body)}if !self.spread.terminal_is_empty(){return self.spread.close_demand(body)}if !self.id.terminal_is_empty(){return self.id.close_demand(body)}if let Some(owner)=self.retirement.as_ref(){return if owner.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<Option<FactoryVectorRetirement<LayoutMutation>>>()*2+256,depth:1,..Default::default()})}else{owner.demands(c.mutations,body)}}if self.rows.is_some(){return Ok(FactoryVectorRetirement::<LayoutMutation>::constructor_demand())}Ok(Default::default())}
 pub fn close_step(&mut self,c:RetainedMutationCloseContext<'_,LayoutMutation>,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(fault())}let d=self.close_demand(c,g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.parent.terminal_is_empty(){return self.parent.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.link.terminal_is_empty(){return self.link.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.story.terminal_is_empty(){return self.story.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.paragraph.terminal_is_empty(){return self.paragraph.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.character.terminal_is_empty(){return self.character.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.spread.terminal_is_empty(){return self.spread.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.id.terminal_is_empty(){return self.id.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if let Some(owner)=self.retirement.as_mut(){if owner.terminal_is_empty(){self.retirement=None;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}return owner.close_step(c.mutations,g).map(|s|RetainedCloneStep::Progress(s.progress()))}if let Some(rows)=self.rows.take(){match FactoryVectorRetirement::admit(rows,g){Ok((owner,p))=>{self.retirement=Some(owner);return Ok(RetainedCloneStep::Progress(p))},Err((error,rows))=>{*self.rows=Some(rows);return Err(error)}}}Ok(RetainedCloneStep::Complete(Default::default()))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.parent.terminal_is_empty()&&self.link.terminal_is_empty()&&self.story.terminal_is_empty()&&self.paragraph.terminal_is_empty()&&self.character.terminal_is_empty()&&self.spread.terminal_is_empty()&&self.id.terminal_is_empty()&&self.rows.is_none()&&self.retirement.is_none()}}
impl Drop for DeletionInverse{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"deleted Layout row inverse needs original funded cleanup")}}
